const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-70.647985, -34.752733]);
  // Define a basin-like area using a buffer around the point (e.g., 20km radius)
  const basin_geom = point.buffer(20000); // 20 km buffer

  const date2021_start = '2021-12-16';
  const date2021_end = '2021-12-20'; // 5-day window around Dec 18, 2021

  const date2023_start = '2023-12-16';
  const date2023_end = '2023-12-20'; // 5-day window around Dec 18, 2023

  const S2_CLOUD_FILTER = 60; // Max percentage of cloud cover allowed in an image.
  const SNOW_NDSI_THRESHOLD = 0.4; // NDSI value >= this is considered snow.
  const SCALE = 30; // Sentinel-2 resolution is 10-20m, use 30m for speed.

  // Function to mask clouds and shadows from Sentinel-2 SR data
  function maskS2clouds(image) {
    const s2a = image.select('QA60').eq(1024); // Bits 10 is clouds, 11 is cirrus
    const s2b = image.select('QA60').eq(2048);
    const s2c = image.select('QA60').eq(128); // Bit 7 is cloud shadow
    const s2d = image.select('QA60').eq(256); // Bit 8 is snow
    const s2e = image.select('QA60').eq(32); // Bit 5 is water

    const cloudBitMask = (1 << 10); // Cloud
    const cirrusBitMask = (1 << 11); // Cirrus
    const shadowBitMask = (1 << 7); // Cloud Shadow
    const snowBitMask = (1 << 8); // Snow

    // Get the QA band.
    const qa = image.select('QA60');

    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0))
                 .and(qa.bitwiseAnd(shadowBitMask).eq(0));

    // Also mask out known water bodies to avoid confusion with snow
    const opt_water_mask = image.select('SCL').eq(6); // SCL 6 is Water

    // Mask out saturated pixels in the blue band (B2)
    const saturated_pixels = image.select('B2').eq(0);

    return image.updateMask(mask).updateMask(opt_water_mask.not()).updateMask(saturated_pixels.not())
                .select(['B2', 'B3', 'B4', 'B8', 'B11', 'SCL'])
                .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDSI and mask non-snow pixels
  function addNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    const snow = ndsi.gte(SNOW_NDSI_THRESHOLD);
    // Mask non-snow pixels, and also pixels identified as water by SCL (value 6)
    // SCL value 11 (snow) is also a good indicator but NDSI is more direct for extent.
    const notWaterSCL = image.select('SCL').neq(6);
    const combined_mask = snow.and(notWaterSCL);

    return image.addBands(ndsi).updateMask(combined_mask);
  }

  // Helper to process a collection for a given date range
  async function getSnowCover(startDate, endDate, geometry, year_str) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', S2_CLOUD_FILTER));

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`${year_str} Images: 0 (No images found)`);
      return null;
    }

    // Apply cloud mask and NDSI
    collection = collection.map(maskS2clouds)
                           .map(addNDSI);

    // Get the first valid image or a composite if multiple exist
    const image = collection.mosaic().clip(geometry);

    // Check if the image still has valid data after masking.
    const validPixels = await image.select('NDSI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    if (validPixels === 0 || validPixels === null) {
      console.log(`${year_str} Images: ${initialSize} (Val: 0.0)`);
      return 0; // No valid snow pixels after processing
    }

    // Calculate snow area (pixels count * pixel area)
    const snowPixels = image.select('NDSI').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: SCALE,
      maxPixels: 1e9
    }).get('NDSI').getInfo();

    if (snowPixels === null) {
      console.log(`${year_str} Images: ${initialSize} (Val: ${validPixels}), Snow Pixels: None`);
      return null; // Calculation failed
    }

    const pixelArea = ee.Number(SCALE).multiply(SCALE).divide(1e6); // Area in km^2
    const snowArea_km2 = ee.Number(snowPixels).multiply(pixelArea).getInfo();

    console.log(`${year_str} Images: ${initialSize} (Val: ${validPixels}), Snow Area: ${snowArea_km2.toFixed(2)} km^2`);
    return snowArea_km2;
  }

  // 2. Data Acquisition & Check for 2021
  const snow_area_2021 = await getSnowCover(date2021_start, date2021_end, basin_geom, '2021');
  if (snow_area_2021 === null) {
    if (snow_area_2021 === 0) console.log("No valid snow pixels for 2021 after processing.");
    else console.log("No data for 2021 or calculation failed.");
    console.log("C1");
    return;
  }

  // 2. Data Acquisition & Check for 2023
  const snow_area_2023 = await getSnowCover(date2023_start, date2023_end, basin_geom, '2023');
  if (snow_area_2023 === null) {
    if (snow_area_2023 === 0) console.log("No valid snow pixels for 2023 after processing.");
    else console.log("No data for 2023 or calculation failed.");
    console.log("C1");
    return;
  }

  // 5. Validation & Final Answer
  if (typeof snow_area_2021 !== 'number' || typeof snow_area_2023 !== 'number') {
    if (snow_area_2021 === 0 && snow_area_2023 === 0) {
      console.log("No valid pixels for either year after masking.");
      console.log("C2");
    } else {
      console.log("Calculation issue for one or both years.");
      console.log("C3");
    }
    return;
  }

  if (snow_area_2023 > snow_area_2021) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

